cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <meta name="description" content="A tech blog showcasing engineering insights, product updates, and community stories from DeployCloud." />
  <style>
    :root {
      --bg: #f6f8fb;
      --surface: #ffffff;
      --surface-alt: #f9fbff;
      --text: #0f172a;
      --muted: #64748b;
      --border: #e2e8f0;
      --accent: #2563eb;
      --accent-soft: #dbeafe;
      --shadow: 0 10px 30px rgba(15, 23, 42, 0.07);
      --radius: 16px;
      --radius-sm: 999px;
      --max: 1200px;
    }

    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
      color: var(--text);
      background: linear-gradient(180deg, #ffffff 0%, var(--bg) 36%, #f8fafc 100%);
      line-height: 1.6;
    }

    a { color: inherit; text-decoration: none; }

    .container { width: min(var(--max), 92vw); margin: 0 auto; }

    header {
      position: sticky;
      top: 0;
      z-index: 20;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid var(--border);
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 14px 0;
      gap: 20px;
    }

    .brand { font-weight: 800; letter-spacing: -0.02em; font-size: 1.15rem; }
    .brand span { color: var(--accent); }

    .nav {
      display: flex;
      gap: 20px;
      align-items: center;
      flex-wrap: wrap;
      position: relative;
    }

    .nav-item { position: relative; }

    .nav-btn, .nav-link {
      color: #0b1222;
      font-weight: 600;
      font-size: 0.95rem;
      border: 0;
      background: transparent;
      cursor: pointer;
      padding: 8px 10px;
      border-radius: 10px;
    }

    .nav-btn:hover, .nav-link:hover { background: #f1f5f9; }

    .mega {
      position: absolute;
      left: 0;
      top: calc(100% + 8px);
      width: min(760px, 90vw);
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 14px;
      box-shadow: var(--shadow);
      padding: 18px;
      display: none;
      grid-template-columns: repeat(3, minmax(0,1fr));
      gap: 12px;
    }

    .mega.open { display: grid; }

    .mega h4 {
      margin: 0 0 8px;
      font-size: 0.8rem;
      color: var(--muted);
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }

    .mega a {
      display: block;
      padding: 8px;
      border-radius: 10px;
      font-weight: 600;
      font-size: 0.92rem;
    }

    .mega a:hover { background: #f8fafc; }

    main { padding: 46px 0 70px; }

    .hero h1 {
      font-size: clamp(1.9rem, 5vw, 3.1rem);
      line-height: 1.15;
      margin: 0;
      letter-spacing: -0.03em;
      max-width: 16ch;
    }

    .hero p { color: var(--muted); max-width: 62ch; margin-top: 14px; }

    .filters-wrap {
      margin-top: 30px;
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 14px;
      justify-content: space-between;
      border-top: 1px solid var(--border);
      border-bottom: 1px solid var(--border);
      padding: 18px 0;
    }

    .pills { display: flex; flex-wrap: wrap; gap: 10px; }

    .pill {
      border: 1px solid var(--border);
      background: #fff;
      border-radius: var(--radius-sm);
      padding: 8px 14px;
      font-weight: 600;
      color: #334155;
      cursor: pointer;
      transition: .2s ease;
    }

    .pill.active {
      background: var(--accent-soft);
      color: #1d4ed8;
      border-color: #bfdbfe;
      box-shadow: inset 0 0 0 1px #93c5fd;
    }

    .search {
      min-width: 220px;
      max-width: 300px;
      width: 100%;
    }

    .search input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 10px 12px;
      font-size: 0.95rem;
      outline: none;
      background: #fff;
    }

    .search input:focus {
      border-color: #93c5fd;
      box-shadow: 0 0 0 3px #dbeafe;
    }

    .section-head {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin: 34px 0 16px;
      gap: 16px;
      flex-wrap: wrap;
    }

    .section-head h2 { margin: 0; font-size: 1.5rem; letter-spacing: -0.02em; }
    .section-head p { margin: 0; color: var(--muted); }

    .featured-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0,1fr));
      gap: 16px;
    }

    .card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 18px;
      box-shadow: 0 1px 0 rgba(15, 23, 42, 0.02);
      transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
    }

    .card:hover {
      transform: translateY(-3px);
      box-shadow: var(--shadow);
      border-color: #cbd5e1;
    }

    .featured {
      background: linear-gradient(155deg, #ffffff 0%, #f8fbff 45%, #eef4ff 100%);
      padding: 20px;
      min-height: 300px;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .meta {
      display: flex;
      gap: 10px;
      align-items: center;
      flex-wrap: wrap;
      font-size: 0.84rem;
      color: var(--muted);
    }

    .tag {
      font-weight: 700;
      color: #1d4ed8;
      background: #eaf2ff;
      padding: 4px 10px;
      border-radius: var(--radius-sm);
      font-size: 0.75rem;
      letter-spacing: .02em;
    }

    .card h3 { margin: 0; line-height: 1.25; letter-spacing: -0.01em; }
    .card p { margin: 0; color: #334155; }

    .stats {
      margin-top: auto;
      display: grid;
      gap: 8px;
      padding: 12px;
      border: 1px dashed #bfdbfe;
      border-radius: 12px;
      background: #eff6ff;
    }

    .stats span { font-size: .84rem; color: #1e3a8a; font-weight: 600; }

    .author {
      margin-top: 14px;
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: .9rem;
      color: #475569;
    }

    .avatar {
      width: 30px;
      height: 30px;
      border-radius: 50%;
      background: linear-gradient(135deg, #2563eb, #0ea5e9);
      color: #fff;
      display: inline-grid;
      place-items: center;
      font-size: 0.74rem;
      font-weight: 700;
    }

    .news-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0,1fr));
      gap: 16px;
    }

    .news-card h3 { font-size: 1.05rem; }
    .news-card p { font-size: 0.94rem; color: #475569; }

    .no-results {
      display: none;
      border: 1px dashed #cbd5e1;
      border-radius: 14px;
      background: #fff;
      padding: 28px;
      text-align: center;
      color: #475569;
      margin-top: 16px;
    }

    .show-more-wrap { margin-top: 22px; display: flex; justify-content: center; }

    .show-more {
      border: 1px solid #bfdbfe;
      background: #eff6ff;
      color: #1d4ed8;
      font-weight: 700;
      border-radius: 12px;
      padding: 10px 16px;
      cursor: pointer;
    }

    .show-more:hover { background: #dbeafe; }
    .show-more:disabled { opacity: .45; cursor: not-allowed; }

    .cta {
      margin-top: 44px;
      background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
      color: #e2e8f0;
      border-radius: 18px;
      padding: 28px;
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: center;
      gap: 14px;
    }

    .cta h3 { margin: 0; color: #fff; font-size: 1.35rem; }
    .cta p { margin: 6px 0 0; max-width: 58ch; }

    .cta a {
      background: #f97316;
      color: #fff;
      padding: 10px 14px;
      border-radius: 10px;
      font-weight: 700;
    }

    footer {
      margin-top: 40px;
      padding: 24px 0 40px;
      color: #64748b;
      border-top: 1px solid var(--border);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0,1fr));
      gap: 16px;
    }

    .footer-grid h4 { margin: 0 0 8px; color: #0f172a; font-size: .95rem; }
    .footer-grid p { margin: 0; font-size: .9rem; }

    @media (max-width: 1020px) {
      .featured-grid, .news-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .footer-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .mega { grid-template-columns: repeat(2, minmax(0,1fr)); }
    }

    @media (max-width: 700px) {
      .featured-grid, .news-grid, .footer-grid { grid-template-columns: 1fr; }
      .topbar { align-items: flex-start; flex-direction: column; }
      .filters-wrap { align-items: stretch; }
      .search { max-width: 100%; }
      .mega { position: static; width: 100%; margin-top: 8px; }
    }
  </style>
</head>
<body>
  <header>
    <div class="container topbar">
      <div class="brand">Deploy<span>Cloud</span> Blog</div>
      <nav class="nav" aria-label="Primary">
        <a class="nav-link" href="#">Blog</a>
        <div class="nav-item" id="productsNav">
          <button class="nav-btn" aria-expanded="false" aria-controls="productsMenu">Products ▾</button>
          <div class="mega" id="productsMenu" role="menu">
            <div>
              <h4>AI Cloud</h4>
              <a href="#">AI Gateway</a>
              <a href="#">Agents Runtime</a>
              <a href="#">Inference Routing</a>
            </div>
            <div>
              <h4>Core Platform</h4>
              <a href="#">Deploy Pipelines</a>
              <a href="#">Edge Functions</a>
              <a href="#">Sandbox Compute</a>
            </div>
            <div>
              <h4>Security</h4>
              <a href="#">Zero Data Retention</a>
              <a href="#">Secrets Manager</a>
              <a href="#">Compliance Center</a>
            </div>
          </div>
        </div>
        <div class="nav-item" id="resourcesNav">
          <button class="nav-btn" aria-expanded="false" aria-controls="resourcesMenu">Resources ▾</button>
          <div class="mega" id="resourcesMenu" role="menu">
            <div>
              <h4>Company</h4>
              <a href="#">About DeployCloud</a>
              <a href="#">Careers</a>
              <a href="#">Press Kit</a>
            </div>
            <div>
              <h4>Learn</h4>
              <a href="#">Docs</a>
              <a href="#">Guides</a>
              <a href="#">Status</a>
            </div>
            <div>
              <h4>Open Source</h4>
              <a href="#">GitHub</a>
              <a href="#">Community Events</a>
              <a href="#">Contribute</a>
            </div>
          </div>
        </div>
      </nav>
    </div>
  </header>

  <main class="container">
    <section class="hero" aria-labelledby="hero-title">
      <h1 id="hero-title">Discover the latest in web development</h1>
      <p>A content hub for developers, engineering teams, and technical decision-makers exploring cloud infrastructure, AI agents, and platform engineering at scale.</p>
    </section>

    <section class="filters-wrap" aria-label="Category and search filters">
      <div class="pills" id="categoryPills"></div>
      <label class="search" for="postSearch">
        <input id="postSearch" type="search" placeholder="Search posts, topics, or keywords" aria-label="Search blog posts" />
      </label>
    </section>

    <section aria-labelledby="featured-heading">
      <div class="section-head">
        <h2 id="featured-heading">Featured articles</h2>
        <p>Editorial picks from the DeployCloud engineering team</p>
      </div>
      <div class="featured-grid" id="featuredGrid"></div>
    </section>

    <section aria-labelledby="latest-heading">
      <div class="section-head">
        <h2 id="latest-heading">Latest news</h2>
        <p>Product updates, engineering stories, and customer insights</p>
      </div>
      <div class="news-grid" id="newsGrid"></div>
      <div class="no-results" id="noResults">No results found. Try another category or search keyword.</div>
      <div class="show-more-wrap"><button id="showMoreBtn" class="show-more">Show more posts</button></div>
    </section>

    <section class="cta" aria-label="Call to action">
      <div>
        <h3>Build and ship with DeployCloud</h3>
        <p>From AI-native apps to enterprise-scale deployment workflows, discover a platform engineered for velocity, safety, and operational clarity.</p>
      </div>
      <a href="#">Start for free</a>
    </section>

    <footer>
      <div class="footer-grid">
        <div>
          <h4>Products</h4>
          <p>AI Cloud · Core Platform · Security</p>
        </div>
        <div>
          <h4>Use Cases</h4>
          <p>Composable Commerce · Web Apps · Platform Engineers</p>
        </div>
        <div>
          <h4>Company</h4>
          <p>About · Careers · Help · Legal</p>
        </div>
        <div>
          <h4>Community</h4>
          <p>Open Source · Events · GitHub · LinkedIn</p>
        </div>
      </div>
    </footer>
  </main>

  <script>
    const categories = ["All Posts", "Engineering", "Community", "Company News", "Customers", "Security"];

    const featuredPosts = [
      {
        title: "Agentic Infrastructure",
        category: "Engineering",
        date: "Apr 10, 2026",
        excerpt: "DeployCloud now observes a major shift toward autonomous delivery flows, where coding agents collaborate with human reviewers to ship production updates faster.",
        author: "Maya Chen"
      },
      {
        title: "A new programming model for durable execution",
        category: "Engineering",
        date: "Apr 02, 2026",
        excerpt: "Durable execution primitives bring deterministic recovery and long-running orchestration to modern cloud apps without sacrificing developer velocity.",
        author: "Devon Park"
      },
      {
        title: "Agent responsibly",
        category: "Security",
        date: "Mar 24, 2026",
        excerpt: "A practical framework for introducing AI agents into deployment workflows with clear observability, guardrails, and incident response patterns.",
        author: "Iris Nolan"
      }
    ];

    const allPosts = [
      { title: "A new programming model for durable execution", category: "Engineering", date: "Apr 02, 2026", excerpt: "How durable workflows let teams recover stateful tasks automatically during failures.", author: "Devon Park" },
      { title: "Zero Data Retention on AI Gateway", category: "Security", date: "Mar 27, 2026", excerpt: "A deep look at request handling paths and retention controls in DeployCloud AI Gateway.", author: "Sonia Li" },
      { title: "Optimizing Sandbox snapshots", category: "Engineering", date: "Mar 22, 2026", excerpt: "Techniques that cut restore times and accelerate reproducible runtime environments.", author: "Caleb Wong" },
      { title: "How a startup made a blog platform work for humans and AI alike", category: "Customers", date: "Mar 14, 2026", excerpt: "A customer story on balancing discoverability, editorial quality, and AI-friendly content architecture.", author: "Rhea Ortiz" },
      { title: "Making build tool 96% faster with agents, sandboxes, and humans", category: "Engineering", date: "Mar 09, 2026", excerpt: "A practical performance case study combining agentic automation with focused human oversight.", author: "Theo Kim" },
      { title: "Unified reporting for all AI Gateway usage", category: "Company News", date: "Mar 03, 2026", excerpt: "Introducing unified telemetry views for teams tracking model costs, reliability, and throughput.", author: "Leah Shah" },
      { title: "Building with our community: spring roadmap", category: "Community", date: "Feb 26, 2026", excerpt: "What we learned from contributors and what’s coming next in the DeployCloud ecosystem.", author: "Alex Grant" },
      { title: "Customer spotlight: FinEdge scales global releases", category: "Customers", date: "Feb 20, 2026", excerpt: "How FinEdge reduced deployment incidents while expanding release frequency across regions.", author: "Priya Desai" },
      { title: "Incident retrospectives in the age of AI copilots", category: "Security", date: "Feb 15, 2026", excerpt: "Patterns for post-incident learning when autonomous systems are part of production workflows.", author: "Noah Gray" },
      { title: "From monorepo to multi-runtime platform", category: "Engineering", date: "Feb 08, 2026", excerpt: "Architecture decisions behind scaling a deployment platform for polyglot teams.", author: "Evan Ross" },
      { title: "DeployCloud docs redesign: speed and clarity", category: "Company News", date: "Feb 02, 2026", excerpt: "We rebuilt docs IA, search quality, and navigation to improve developer onboarding.", author: "Mina Patel" },
      { title: "Security baseline templates for regulated teams", category: "Security", date: "Jan 25, 2026", excerpt: "Reusable controls and workflow defaults for finance and healthcare engineering teams.", author: "Omar Bell" }
    ];

    const initialVisible = 6;
    const showStep = 3;
    let visibleCount = initialVisible;
    let activeCategory = "All Posts";
    let searchTerm = "";

    const pillsContainer = document.getElementById("categoryPills");
    const featuredGrid = document.getElementById("featuredGrid");
    const newsGrid = document.getElementById("newsGrid");
    const noResults = document.getElementById("noResults");
    const searchInput = document.getElementById("postSearch");
    const showMoreBtn = document.getElementById("showMoreBtn");

    function initials(name) {
      return name.split(" ").map(part => part[0]).join("").slice(0, 2).toUpperCase();
    }

    function createCard(post, featured = false) {
      const article = document.createElement("article");
      article.className = `card ${featured ? "featured" : "news-card"}`;
      article.innerHTML = `
        <div class="meta">
          <span class="tag">${post.category}</span>
          <span>${post.date}</span>
        </div>
        <h3>${post.title}</h3>
        <p>${post.excerpt}</p>
        ${featured && post.title === "Agentic Infrastructure" ? `
          <div class="stats" aria-label="Agentic infrastructure stats">
            <span>30% of deployments initiated by coding agents</span>
            <span>1000% increase from six months ago</span>
            <span>20× more likely to call AI inference</span>
          </div>
        ` : ""}
        <div class="author">
          <span class="avatar">${initials(post.author)}</span>
          <span>${post.author}</span>
        </div>
      `;
      return article;
    }

    function renderFeatured() {
      featuredGrid.innerHTML = "";
      featuredPosts.forEach(post => featuredGrid.appendChild(createCard(post, true)));
    }

    function filteredPosts() {
      return allPosts.filter(post => {
        const categoryMatch = activeCategory === "All Posts" || post.category === activeCategory;
        const q = searchTerm.trim().toLowerCase();
        const searchMatch = !q || [post.title, post.excerpt, post.category, post.author].join(" ").toLowerCase().includes(q);
        return categoryMatch && searchMatch;
      });
    }

    function renderNews(reset = false) {
      const posts = filteredPosts();
      if (reset) newsGrid.innerHTML = "";

      const displayed = posts.slice(0, visibleCount);
      newsGrid.innerHTML = "";
      displayed.forEach(post => newsGrid.appendChild(createCard(post)));

      noResults.style.display = displayed.length ? "none" : "block";
      showMoreBtn.style.display = posts.length > 0 ? "inline-block" : "none";
      showMoreBtn.disabled = displayed.length >= posts.length;
      showMoreBtn.textContent = showMoreBtn.disabled ? "All posts loaded" : "Show more posts";
    }

    function renderPills() {
      pillsContainer.innerHTML = "";
      categories.forEach(category => {
        const button = document.createElement("button");
        button.className = `pill ${activeCategory === category ? "active" : ""}`;
        button.textContent = category;
        button.setAttribute("type", "button");
        button.addEventListener("click", () => {
          activeCategory = category;
          visibleCount = initialVisible;
          renderPills();
          renderNews(true);
        });
        pillsContainer.appendChild(button);
      });
    }

    searchInput.addEventListener("input", (event) => {
      searchTerm = event.target.value;
      visibleCount = initialVisible;
      renderNews(true);
    });

    showMoreBtn.addEventListener("click", () => {
      visibleCount += showStep;
      renderNews();
    });

    function setupMegaMenu(navId, menuId) {
      const nav = document.getElementById(navId);
      const button = nav.querySelector("button");
      const menu = document.getElementById(menuId);

      function openMenu() {
        menu.classList.add("open");
        button.setAttribute("aria-expanded", "true");
      }

      function closeMenu() {
        menu.classList.remove("open");
        button.setAttribute("aria-expanded", "false");
      }

      button.addEventListener("click", (event) => {
        event.stopPropagation();
        const isOpen = menu.classList.contains("open");
        document.querySelectorAll('.mega.open').forEach(el => el.classList.remove('open'));
        document.querySelectorAll('.nav-btn[aria-expanded="true"]').forEach(el => el.setAttribute('aria-expanded', 'false'));
        if (!isOpen) openMenu();
      });

      nav.addEventListener("mouseenter", openMenu);
      nav.addEventListener("mouseleave", closeMenu);
      document.addEventListener("click", (event) => {
        if (!nav.contains(event.target)) closeMenu();
      });
    }

    renderFeatured();
    renderPills();
    renderNews(true);
    setupMegaMenu("productsNav", "productsMenu");
    setupMegaMenu("resourcesNav", "resourcesMenu");
  </script>
</body>
</html>
HTML

