      position: absolute;
      left: 0;
      top: calc(100% + 8px);
      width: min(760px, 90vw);
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 14px;
      box-shadow: var(--shadow);
      padding: 18px;
      display: none;
      grid-template-columns: repeat(3, minmax(0,1fr));
      gap: 12px;
    }

    .mega.open { display: grid; }

    .mega h4 {
      margin: 0 0 8px;
      font-size: 0.8rem;
      color: var(--muted);
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }

    .mega a {
      display: block;
      padding: 8px;
      border-radius: 10px;
      font-weight: 600;
      font-size: 0.92rem;
    }

    .mega a:hover { background: #f8fafc; }

    main { padding: 46px 0 70px; }

    .hero h1 {
      font-size: clamp(1.9rem, 5vw, 3.1rem);
      line-height: 1.15;
      margin: 0;
      letter-spacing: -0.03em;
      max-width: 16ch;
    }

    .hero p { color: var(--muted); max-width: 62ch; margin-top: 14px; }

    .filters-wrap {
      margin-top: 30px;
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 14px;
      justify-content: space-between;
      border-top: 1px solid var(--border);
      border-bottom: 1px solid var(--border);
      padding: 18px 0;
    }

    .pills { display: flex; flex-wrap: wrap; gap: 10px; }

    .pill {
      border: 1px solid var(--border);
      background: #fff;
      border-radius: var(--radius-sm);
      padding: 8px 14px;
      font-weight: 600;
      color: #334155;
      cursor: pointer;
      transition: .2s ease;
    }

    .pill.active {
      background: var(--accent-soft);
      color: #1d4ed8;
      border-color: #bfdbfe;
      box-shadow: inset 0 0 0 1px #93c5fd;
    }

    .search {
      min-width: 220px;
      max-width: 300px;
      width: 100%;
    }

    .search input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 10px 12px;
      font-size: 0.95rem;
      outline: none;
      background: #fff;
    }

    .search input:focus {
      border-color: #93c5fd;
      box-shadow: 0 0 0 3px #dbeafe;
    }

    .section-head {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin: 34px 0 16px;
      gap: 16px;
      flex-wrap: wrap;
    }

    .section-head h2 { margin: 0; font-size: 1.5rem; letter-spacing: -0.02em; }
    .section-head p { margin: 0; color: var(--muted); }

    .featured-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0,1fr));
      gap: 16px;
    }

    .card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 18px;
      box-shadow: 0 1px 0 rgba(15, 23, 42, 0.02);
      transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
    }

    .card:hover {
      transform: translateY(-3px);
      box-shadow: var(--shadow);
      border-color: #cbd5e1;
    }

    .featured {
      background: linear-gradient(155deg, #ffffff 0%, #f8fbff 45%, #eef4ff 100%);
      padding: 20px;
      min-height: 300px;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .meta {
      display: flex;
      gap: 10px;
      align-items: center;
      flex-wrap: wrap;
      font-size: 0.84rem;
      color: var(--muted);
    }

    .tag {
      font-weight: 700;
      color: #1d4ed8;
      background: #eaf2ff;
      padding: 4px 10px;
      border-radius: var(--radius-sm);
      font-size: 0.75rem;
      letter-spacing: .02em;
    }

    .card h3 { margin: 0; line-height: 1.25; letter-spacing: -0.01em; }
    .card p { margin: 0; color: #334155; }

    .stats {
      margin-top: auto;
      display: grid;
      gap: 8px;
      padding: 12px;
      border: 1px dashed #bfdbfe;
      border-radius: 12px;
      background: #eff6ff;
    }

    .stats span { font-size: .84rem; color: #1e3a8a; font-weight: 600; }

    .author {
      margin-top: 14px;
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: .9rem;
      color: #475569;
    }

    .avatar {
      width: 30px;
      height: 30px;
      border-radius: 50%;
      background: linear-gradient(135deg, #2563eb, #0ea5e9);
      color: #fff;
      display: inline-grid;
      place-items: center;
      font-size: 0.74rem;
      font-weight: 700;
    }

    .news-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0,1fr));
      gap: 16px;
    }

    .news-card h3 { font-size: 1.05rem; }
    .news-card p { font-size: 0.94rem; color: #475569; }

    .no-results {
      display: none;
      border: 1px dashed #cbd5e1;
      border-radius: 14px;
      background: #fff;
      padding: 28px;
      text-align: center;
      color: #475569;
      margin-top: 16px;
    }

    .show-more-wrap { margin-top: 22px; display: flex; justify-content: center; }

    .show-more {
      border: 1px solid #bfdbfe;
      background: #eff6ff;
      color: #1d4ed8;
      font-weight: 700;
      border-radius: 12px;
      padding: 10px 16px;
      cursor: pointer;
    }

    .show-more:hover { background: #dbeafe; }
    .show-more:disabled { opacity: .45; cursor: not-allowed; }

    .cta {
      margin-top: 44px;
      background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
      color: #e2e8f0;
      border-radius: 18px;
      padding: 28px;
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: center;
      gap: 14px;
    }

    .cta h3 { margin: 0; color: #fff; font-size: 1.35rem; }
    .cta p { margin: 6px 0 0; max-width: 58ch; }

    .cta a {
      background: #f97316;
      color: #fff;
      padding: 10px 14px;
      border-radius: 10px;
      font-weight: 700;
    }

    footer {
      margin-top: 40px;
      padding: 24px 0 40px;
      color: #64748b;
      border-top: 1px solid var(--border);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0,1fr));
      gap: 16px;
    }

    .footer-grid h4 { margin: 0 0 8px; color: #0f172a; font-size: .95rem; }
    .footer-grid p { margin: 0; font-size: .9rem; }

    @media (max-width: 1020px) {
      .featured-grid, .news-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .footer-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .mega { grid-template-columns: repeat(2, minmax(0,1fr)); }
    }

    @media (max-width: 700px) {
      .featured-grid, .news-grid, .footer-grid { grid-template-columns: 1fr; }
      .topbar { align-items: flex-start; flex-direction: column; }
      .filters-wrap { align-items: stretch; }
      .search { max-width: 100%; }
      .mega { position: static; width: 100%; margin-top: 8px; }
    }
  </style>
</head>
<body>
  <header>
    <div class="container topbar">
      <div class="brand">Deploy<span>Cloud</span> Blog</div>
      <nav class="nav" aria-label="Primary">
        <a class="nav-link" href="#">Blog</a>
        <div class="nav-item" id="productsNav">
          <button class="nav-btn" aria-expanded="false" aria-controls="productsMenu">Products ▾</button>
          <div class="mega" id="productsMenu" role="menu">
            <div>
