        <div class="nav-item" id="resourcesNav">
          <button class="nav-btn" aria-expanded="false" aria-controls="resourcesMenu">Resources ▾</button>
          <div class="mega" id="resourcesMenu" role="menu">
            <div>
              <h4>Company</h4>
